INSERT IGNORE INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES
(121, 12, 4, 'Вернуть список команд', 0, '{\"transitions_before\": [{\"variable\": \"prompt_user\", \"operator\": \"==\", \"value\": \"/new_case\", \"step_id\": \"122\"}, {\"variable\": \"prompt_user\", \"operator\": \"==\", \"value\": \"/accuse\", \"step_id\": \"131\"}], \"transitions_after\": [], \"prompt_user\": \"%agent_greeting%\", \"continue_workflow\": false}'),
(122, 12, 2, 'Сгенерировать дело', 1, '{\"transitions_before\": [], \"transitions_after\": [], \"llm_to_json_variable\": [{\"variable\": \"victim_name\", \"text\": \"имя жертвы\"}, {\"variable\": \"crime_description\", \"text\": \"описание преступления для игрока, без намека на виновного\"}, {\"variable\": \"guilty_suspect_name\", \"text\": \"имя виновного подозреваемого\"}, {\"variable\": \"solution_reveal\", \"text\": \"финальная разгадка дела\"}, {\"variable\": \"suspect_1_name\", \"text\": \"имя подозреваемого 1\"}, {\"variable\": \"suspect_1_sheet\", \"text\": \"легенда подозреваемого 1\"}, {\"variable\": \"suspect_1_greeting\", \"text\": \"приветствие подозреваемого 1\"}, {\"variable\": \"suspect_2_name\", \"text\": \"имя подозреваемого 2\"}, {\"variable\": \"suspect_2_sheet\", \"text\": \"легенда подозреваемого 2\"}, {\"variable\": \"suspect_2_greeting\", \"text\": \"приветствие подозреваемого 2\"}, {\"variable\": \"suspect_3_name\", \"text\": \"имя подозреваемого 3\"}, {\"variable\": \"suspect_3_sheet\", \"text\": \"легенда подозреваемого 3\"}, {\"variable\": \"suspect_3_greeting\", \"text\": \"приветствие подозреваемого 3\"}, {\"variable\": \"suspect_4_name\", \"text\": \"имя подозреваемого 4\"}, {\"variable\": \"suspect_4_sheet\", \"text\": \"легенда подозреваемого 4\"}, {\"variable\": \"suspect_4_greeting\", \"text\": \"приветствие подозреваемого 4\"}, {\"variable\": \"autopsy_report\", \"text\": \"отчет судмедэксперта о вскрытии\"}, {\"variable\": \"evidence_report\", \"text\": \"отчет полиции о найденных на месте уликах\"}, {\"variable\": \"witness_statements\", \"text\": \"показания свидетелей (не подозреваемых)\"}, {\"variable\": \"bank_records\", \"text\": \"банковские записи, релевантные подозреваемым\"}, {\"variable\": \"scene_inventory\", \"text\": \"опись примечательных предметов на месте преступления\"}, {\"variable\": \"suspect_1_interrogation\", \"text\": \"протокол предварительного допроса подозреваемого 1 полицией\"}, {\"variable\": \"suspect_2_interrogation\", \"text\": \"протокол предварительного допроса подозреваемого 2 полицией\"}, {\"variable\": \"suspect_3_interrogation\", \"text\": \"протокол предварительного допроса подозреваемого 3 полицией\"}, {\"variable\": \"suspect_4_interrogation\", \"text\": \"протокол предварительного допроса подозреваемого 4 полицией\"}, {\"variable\": \"suspect_1_brief\", \"text\": \"краткая опорная справка по подозреваемому 1: алиби в двух словах + мотив\"}, {\"variable\": \"suspect_2_brief\", \"text\": \"краткая опорная справка по подозреваемому 2: алиби в двух словах + мотив\"}, {\"variable\": \"suspect_3_brief\", \"text\": \"краткая опорная справка по подозреваемому 3: алиби в двух словах + мотив\"}, {\"variable\": \"suspect_4_brief\", \"text\": \"краткая опорная справка по подозреваемому 4: алиби в двух словах + мотив\"}], \"prompt_user\": \"Придумай честное, разрешимое детективное дело в жанре классического детектива (как Агата Кристи). Правила:\\n\\n1. Ровно 4 подозреваемых с разными именами.\\n2. Ровно один из них виновен в убийстве.\\n3. У каждого подозреваемого есть алиби, личность, отношение к жертве и мотив (или его отсутствие).\\n4. Алиби невиновных подозреваемых логически непротиворечивы и не имеют дыр.\\n5. Алиби виновного имеет ОДНУ подходящую, но не самоочевидную нестыковку (например, упоминает деталь, которая противоречит времени/месту/показаниям другого подозреваемого) - ее можно найти, если задать точные уточняющие вопросы, но виновный сам никогда не признается напрямую.\\n6. Все подозреваемые знают общие факты дела (время, место, орудие) одинаково - не противоречь себе между персонажами.\\n7. Пиши строго на языке: %user_language%.\\n\\n=== Что нужно вернуть (основное дело) ===\\n- victim_name: имя жертвы\\n- crime_description: 2-4 предложения для игрока: кто жертва, где и как произошло убийство, орудие, примерное время - БЕЗ намека на виновного\\n- guilty_suspect_name: имя виновного (должно точно совпадать с одним из suspect_N_name)\\n- solution_reveal: финальная разгадка на 3-5 предложений, которая будет показана игроку ПОСЛЕ обвинения - объясняет мотив виновного и в чем именно была нестыковка в его алиби\\n- suspect_1_name, suspect_2_name, suspect_3_name, suspect_4_name: имена подозреваемых\\n- suspect_1_sheet, suspect_2_sheet, suspect_3_sheet, suspect_4_sheet: полная легенда персонажа текстом (5-8 предложений): кто он жертве, где был во время убийства (алиби), характер, как себя ведет на допросе. Для виновного - явно опиши его мотив и ОСТОРОЖНО впиши нестыковку в алиби, но не пиши прямо \'он виновен\'\\n- suspect_1_greeting, suspect_2_greeting, suspect_3_greeting, suspect_4_greeting: короткая фраза (1 предложение) в характере, которой подозреваемый встречает детектива на допросе\\n\\n=== Дополнительные материалы дела (для сержанта полиции и досье) - ВСЕ должны быть согласованы друг с другом и с основным делом выше, без противоречий ===\\n- autopsy_report (3-5 предложений): заключение судмедэксперта - причина смерти, орудие, примерное время смерти, дополнительные медицинские наблюдения. Должно согласовываться с crime_description и с нестыковкой в алиби виновного.\\n- evidence_report (3-5 предложений): улики, найденные на месте преступления (отпечатки, посторонние предметы, следы борьбы и т.п.) - дают зацепки, но не раскрывают виновного напрямую.\\n- witness_statements (2-3 показания): что видели/слышали свидетели (НЕ подозреваемые, например соседи, прислуга, прохожие) - без прямого разоблачения виновного.\\n- bank_records (2-4 предложения): финансовые записи 1-2 подозреваемых с мотивом (долги, недавние переводы, наследство) - правдоподобный финансовый мотив.\\n- scene_inventory (4-6 предметов списком): примечательные предметы, найденные в помещении/на месте преступления, часть из которых может быть уликами.\\n- suspect_1_interrogation, suspect_2_interrogation, suspect_3_interrogation, suspect_4_interrogation (3-5 предложений каждый): протокол ПЕРВИЧНОГО опроса подозреваемого полицией (до начала игры) - должен покрывать: краткое алиби, род занятий/профессию, физические приметы (рост, телосложение, возраст), характер отношений с жертвой, семейное положение. Должен ТОЧНО СОВПАДАТЬ с фактами из suspect_N_sheet, не противоречить им.\\n- suspect_1_brief, suspect_2_brief, suspect_3_brief, suspect_4_brief (ОДНО короткое предложение каждый, 10-15 слов): опорная справка для игрока сразу под именем подозреваемого в списке - алиби в двух словах + есть ли видимый мотив. Например: \'Утверждает, что был в своей комнате всю ночь; видимого мотива нет.\' или \'Был в саду; крупный долг перед жертвой.\' ДОЛЖНО совпадать по сути с suspect_N_interrogation и suspect_N_sheet, просто короче.\\n\\n=== Important information about final response ===\\nPlease return your response in JSON format with exactly these keys: victim_name, crime_description, guilty_suspect_name, solution_reveal, suspect_1_name, suspect_1_sheet, suspect_1_greeting, suspect_2_name, suspect_2_sheet, suspect_2_greeting, suspect_3_name, suspect_3_sheet, suspect_3_greeting, suspect_4_name, suspect_4_sheet, suspect_4_greeting, autopsy_report, evidence_report, witness_statements, bank_records, scene_inventory, suspect_1_interrogation, suspect_2_interrogation, suspect_3_interrogation, suspect_4_interrogation, suspect_1_brief, suspect_2_brief, suspect_3_brief, suspect_4_brief.\"}'),
(123, 12, 3, 'agent_workflow_id_talk', 2, '{\"transitions_before\": [], \"transitions_after\": [], \"tool_invoke\": {\"tool_name\": \"agent_workflow_id\", \"inputs_map\": {\"name\": \"detective_talk_workflow_name\"}, \"outputs_map\": {}}}'),
(124, 12, 3, 'Собрать очередь подозреваемых', 3, '{\"transitions_before\": [], \"transitions_after\": [], \"tool_invoke\": {\"tool_name\": \"detective_suspects_queue_build\", \"inputs_map\": {\"session_uuid\": \"session_uuid\", \"suspect_1_name\": \"suspect_1_name\", \"suspect_1_sheet\": \"suspect_1_sheet\", \"suspect_1_greeting\": \"suspect_1_greeting\", \"suspect_1_interrogation\": \"suspect_1_interrogation\", \"suspect_2_name\": \"suspect_2_name\", \"suspect_2_sheet\": \"suspect_2_sheet\", \"suspect_2_greeting\": \"suspect_2_greeting\", \"suspect_2_interrogation\": \"suspect_2_interrogation\", \"suspect_3_name\": \"suspect_3_name\", \"suspect_3_sheet\": \"suspect_3_sheet\", \"suspect_3_greeting\": \"suspect_3_greeting\", \"suspect_3_interrogation\": \"suspect_3_interrogation\", \"suspect_4_name\": \"suspect_4_name\", \"suspect_4_sheet\": \"suspect_4_sheet\", \"suspect_4_greeting\": \"suspect_4_greeting\", \"suspect_4_interrogation\": \"suspect_4_interrogation\"}, \"outputs_map\": {}}}'),
(129, 12, 3, 'Сохранить дело', 8, '{\"transitions_before\": [], \"transitions_after\": [], \"tool_invoke\": {\"tool_name\": \"detective_case_create\", \"inputs_map\": {\"session_uuid\": \"session_uuid\", \"user_id\": \"user_id\", \"victim_name\": \"victim_name\", \"crime_description\": \"crime_description\", \"guilty_suspect_name\": \"guilty_suspect_name\", \"solution_reveal\": \"solution_reveal\"}, \"outputs_map\": {}}}'),
(130, 12, 4, 'Дело открыто', 9, '{\"prompt_user\": \"🕵️ Открыто новое дело\\n\\nЖертва: %victim_name%\\n\\n%crime_description%\\n\\n📋 Сержант Ковальски докладывает: сразу после обнаружения тела полиция собрала первичные данные.\\n\\nВскрытие: %autopsy_report%\\n\\nПодозреваемые:\\n[[%suspect_1_name%]] — %suspect_1_brief%\\n[[%suspect_2_name%]] — %suspect_2_brief%\\n[[%suspect_3_name%]] — %suspect_3_brief%\\n[[%suspect_4_name%]] — %suspect_4_brief%\\n\\nПолное досье (улики, свидетели, банк, опись места) можно узнать у Сержанта полиции в списке агентов.\\n\\nВыбери подозреваемого в списке слева и начни допрос. Когда будешь готов назвать виновного, напиши /accuse.\", \"continue_workflow\": false, \"transitions_after\": [], \"transitions_before\": []}'),
(131, 12, 3, 'Список подозреваемых дела', 10, '{\"transitions_before\": [], \"transitions_after\": [], \"tool_invoke\": {\"tool_name\": \"detective_case_suspects_list\", \"inputs_map\": {\"session_uuid\": \"session_uuid\"}, \"outputs_map\": {}}}'),
(132, 12, 4, 'Спросить кого обвиняем', 11, '{\"transitions_before\": [], \"transitions_after\": [], \"prompt_user\": \"Кого ты обвиняешь в убийстве %detective_case_suspects_list_131_result_victim_name%?\\n\\n%detective_case_suspects_list_131_result_chips%\", \"continue_workflow\": true}'),
(133, 12, 3, 'Проверить вердикт', 12, '{\"transitions_before\": [], \"transitions_after\": [], \"tool_invoke\": {\"tool_name\": \"detective_case_verdict_check\", \"inputs_map\": {\"session_uuid\": \"session_uuid\", \"accused_name\": \"prompt_user\"}, \"outputs_map\": {}}}'),
(134, 12, 4, 'Вердикт', 13, '{\"transitions_before\": [], \"transitions_after\": [], \"prompt_user\": \"%if detective_case_verdict_check_133_result_correct%✅ Верно! Убийца — %detective_case_verdict_check_133_result_guilty_suspect_name%.\\n\\n%detective_case_verdict_check_133_result_solution_reveal%%else%❌ Мимо. Настоящий убийца — %detective_case_verdict_check_133_result_guilty_suspect_name%.\\n\\n%detective_case_verdict_check_133_result_solution_reveal%%endif%\\n\\nЧтобы начать новое дело, напиши /new_case.\", \"continue_workflow\": false}'),
(135, 13, 3, 'session_messages', 0, '{\"transitions_before\": [], \"transitions_after\": [], \"tool_invoke\": {\"tool_name\": \"session_messages\", \"inputs_map\": {\"session_uuid\": \"session_uuid\", \"limit\": \"session_messages_limit\"}, \"outputs_map\": {}}}'),
(136, 13, 1, 'Ответ подозреваемого', 1, '{\"transitions_before\": [], \"transitions_after\": [], \"prompt_user\": \"%if session_messages_135_result_str%=== История допроса ===\\n%session_messages_135_result_str%\\n\\n%endif%=== %companion_title% спрашивает ===\\n%prompt_user%\\n\\nОтветь коротко (1-3 предложения), от первого лица, оставаясь в характере. Отвечай на языке: %user_language%.\"}'),
(137, 14, 3, 'Извлечь из очереди', 0, '{\"transitions_before\": [], \"transitions_after\": [], \"tool_invoke\": {\"tool_name\": \"list_shift\", \"inputs_map\": {\"items\": \"suspects_queue\"}, \"outputs_map\": {}}}'),
(138, 14, 5, 'Собрать системный промпт', 1, '{\"transitions_before\": [], \"transitions_after\": [], \"variable_conversion\": [{\"variable\": \"current_suspect_prompt_system\", \"text\": \"Ты подозреваемый по имени %list_shift_137_result_name% в деле об убийстве %victim_name%. Тебя допрашивает детектив (%companion_title%). Отвечай от первого лица, коротко и естественно, как в живом разговоре при допросе (1-3 предложения). Никогда не выходи из роли и не признавайся, что ты вымышленный персонаж. Если невиновен - говоришь правду, можешь немного нервничать от неприятных вопросов. Если виновен - отрицаешь причастность и не признаешься напрямую, но при точных уточняющих вопросах об алиби можешь путаться в деталях. Никогда сам не заявляешь \'я не виновен\' без повода - отвечай строго по существу заданного вопроса. Оставайся последовательным с тем, что уже сказал(а) полиции при первичном опросе - не противоречь себе. Отвечай на языке: %user_language%.\\n\\n=== Твоя легенда ===\\n%list_shift_137_result_sheet%\\n\\n=== Что ты уже рассказал(а) полиции при первичном опросе ===\\n%list_shift_137_result_interrogation%\"}]}'),
(139, 14, 3, 'Создать агента', 2, '{\"transitions_before\": [], \"transitions_after\": [], \"tool_invoke\": {\"tool_name\": \"agent_create_or_update\", \"inputs_map\": {\"name\": \"list_shift_137_result_agent_name\", \"title\": \"list_shift_137_result_name\", \"node_id\": \"node_id\", \"workflow_id\": \"talk_workflow_id\", \"prompt_system\": \"current_suspect_prompt_system\", \"greeting\": \"list_shift_137_result_greeting\", \"user_id\": \"user_id\"}, \"outputs_map\": {}}}'),
(140, 12, 6, 'Создать подозреваемых (цикл)', 4, '{\"transitions_before\": [], \"transitions_after\": [], \"workflow_invoke\": {\"workflow_id\": 14, \"inputs_map\": {\"suspects_queue\": \"detective_suspects_queue_build_124_result_list\", \"node_id\": \"node_id\", \"talk_workflow_id\": \"agent_workflow_id_123_result_int\", \"victim_name\": \"victim_name\", \"companion_title\": \"companion_title\", \"user_id\": \"user_id\"}, \"outputs_map\": {\"list_shift_137_result_rest\": \"detective_suspects_queue_build_124_result_list\"}, \"repeat\": {\"count\": 4}}}'),
(141, 12, 5, 'Собрать промпт сержанта', 5, '{\"transitions_before\": [], \"transitions_after\": [], \"variable_conversion\": [{\"variable\": \"sergeant_agent_name\", \"text\": \"sergeant_%session_uuid%\"}, {\"variable\": \"sergeant_title\", \"text\": \"Сержант полиции\"}, {\"variable\": \"sergeant_greeting\", \"text\": \"Сержант Ковальски. Чем могу помочь, детектив?\"}, {\"variable\": \"sergeant_prompt_system\", \"text\": \"Ты сержант полиции, ведешь расследование в деле об убийстве %victim_name%. Помогаешь детективу (%companion_title%) дополнительной информацией по запросу: результаты вскрытия, улики, показания свидетелей, банковские записи, опись места преступления, а также предварительные протоколы допроса подозреваемых. Отвечай по существу заданного вопроса, кратко и по-деловому (2-4 предложения), как опытный полицейский. Если вопрос выходит за рамки известных тебе материалов - честно скажи, что этой информации нет в деле. Ты НЕ ЗНАЕШЬ, кто виновен - не называй и не обвиняй никого прямо, просто честно приводи факты из материалов дела, даже если они наводят на подозрения; выводы делает сам детектив. Отвечай на языке: %user_language%.\\n\\n=== ВСКРЫТИЕ ===\\n%autopsy_report%\\n\\n=== УЛИКИ ===\\n%evidence_report%\\n\\n=== ПОКАЗАНИЯ СВИДЕТЕЛЕЙ ===\\n%witness_statements%\\n\\n=== БАНКОВСКИЕ ЗАПИСИ ===\\n%bank_records%\\n\\n=== ОПИСЬ МЕСТА ПРЕСТУПЛЕНИЯ ===\\n%scene_inventory%\\n\\n=== ПРЕДВАРИТЕЛЬНЫЕ ДОПРОСЫ ПОДОЗРЕВАЕМЫХ ===\\n%suspect_1_name%: %suspect_1_interrogation%\\n%suspect_2_name%: %suspect_2_interrogation%\\n%suspect_3_name%: %suspect_3_interrogation%\\n%suspect_4_name%: %suspect_4_interrogation%\"}]}'),
(142, 12, 3, 'Создать сержанта', 6, '{\"transitions_before\": [], \"transitions_after\": [], \"tool_invoke\": {\"tool_name\": \"agent_create_or_update\", \"inputs_map\": {\"name\": \"sergeant_agent_name\", \"title\": \"sergeant_title\", \"node_id\": \"node_id\", \"workflow_id\": \"agent_workflow_id_123_result_int\", \"prompt_system\": \"sergeant_prompt_system\", \"greeting\": \"sergeant_greeting\", \"user_id\": \"user_id\"}, \"outputs_map\": {}}}');
